with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , PREV_POL_CLM_AMT as TOTAL_CLAIM_AMOUNT
        , cast(null as varchar) as TOTAL_CLAIM_COUNT
        , 'BJAZ_HAT_ID_MEM_DETLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_id_mem_detls') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PART_ID))) as HUB_PARTY_HK
        , AMOUNT_CLAIMED as TOTAL_CLAIM_AMOUNT
        , cast(null as varchar) as TOTAL_CLAIM_COUNT
        , 'BJAZ_HC_PART_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hc_part_extn') }}
    where (nullif(trim(PART_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as TOTAL_CLAIM_AMOUNT
        , CLAIM_COUNT as TOTAL_CLAIM_COUNT
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(MEMBER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , AMOUNT_CLAIMED as TOTAL_CLAIM_AMOUNT
        , CLAIM_HISTORY as TOTAL_CLAIM_COUNT
        , 'BJAZ_IHG_MEM_DTLS_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ihg_mem_dtls_extn') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , AMOUNT_CLAIMED as TOTAL_CLAIM_AMOUNT
        , CLAIM_HISTORY as TOTAL_CLAIM_COUNT
        , 'BJAZ_SH_MEM_DTLS_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_sh_mem_dtls_extn') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TOTAL_CLAIM_AMOUNT end) as TOTAL_CLAIM_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TOTAL_CLAIM_COUNT end) as TOTAL_CLAIM_COUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when TOTAL_CLAIM_AMOUNT is not null or TOTAL_CLAIM_COUNT is not null
                     then md5(upper(coalesce(cast(TOTAL_CLAIM_AMOUNT as varchar), '') || '|' || coalesce(cast(TOTAL_CLAIM_COUNT as varchar), '')))
                end as SAT_PARTY_CLAIM_HISTORY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_CLAIM_HISTORY_HASHDIFF is not null
